"""
calc_inv.py — Hotel Inventory · Standalone
Genera INVENTORY_WNN.html completo desde el dataset de contratos.

Uso:
    python calc_inv.py

Configurar las variables de la sección CONFIG antes de correr.
"""

import pandas as pd
import numpy as np
from pathlib import Path
from datetime import datetime, date
import json, sys

# Forzar UTF-8 en stdout/stderr (Windows usa cp1252 por defecto y rompe con emojis/acentos)
try:
    sys.stdout.reconfigure(encoding='utf-8')
    sys.stderr.reconfigure(encoding='utf-8')
except Exception:
    pass

# ─────────────────────────────────────────────
# CONFIG — auto-calculado desde la fecha del sistema (W28+)
# ─────────────────────────────────────────────
# Se calcula automáticamente asumiendo que el script se corre el lunes de
# la semana que se está reportando. Calibrado con W26 → snapshot 29-jun-2026
# (semana ISO 27, WEEK_NUM 26 → offset ISO-1).
#
# Si necesitás forzar una semana específica (corriste tarde, re-generás una
# semana vieja, etc.), completá WEEK_NUM_OVERRIDE y SNAPSHOT_DATE_OVERRIDE
# abajo — si están seteados, tienen prioridad sobre el auto-cálculo.
WEEK_NUM_OVERRIDE      = 27
SNAPSHOT_DATE_OVERRIDE = "6 de Julio de 2026"

_MESES_ES = {1:'Enero',2:'Febrero',3:'Marzo',4:'Abril',5:'Mayo',6:'Junio',
             7:'Julio',8:'Agosto',9:'Septiembre',10:'Octubre',11:'Noviembre',12:'Diciembre'}
_today = datetime.now()
_iso_year, _iso_week, _ = _today.isocalendar()

WEEK_NUM      = WEEK_NUM_OVERRIDE if WEEK_NUM_OVERRIDE is not None else (_iso_week - 1)
WEEK          = f"W{WEEK_NUM:02d}"
VOL_NUM       = f"{WEEK_NUM:02d}"
YEAR_ACTUAL   = _iso_year
SNAPSHOT_DATE = SNAPSHOT_DATE_OVERRIDE if SNAPSHOT_DATE_OVERRIDE else f"{_today.day} de {_MESES_ES[_today.month]} de {_today.year}"
SNAPSHOT_DATE_UPPER = SNAPSHOT_DATE.upper()
INPUT_FILE    = "dataHoteles_contratos.xlsx"
OUTPUT_FILE   = f"INVENTORY_{WEEK}.html"
OUTPUT_DIR    = Path(f"week-{WEEK_NUM:02d}")  # outputs → week-NN/
TARGET_PROPIO = 70_000
TOTAL_WEEKS_2026 = 52
SEMANAS_RESTANTES = max(1, TOTAL_WEEKS_2026 - WEEK_NUM)

print(f"[CONFIG] Auto-detectado: {WEEK} · Snapshot {SNAPSHOT_DATE} · Año {YEAR_ACTUAL}")
print(f"[CONFIG] Si esto está mal, completá WEEK_NUM_OVERRIDE / SNAPSHOT_DATE_OVERRIDE arriba y volvé a correr.\n")

# Logo PriceTravel (base64 — mismo que CR/RND)
LOGO_B64 = "data:image/png;base64,"

# ─────────────────────────────────────────────
# HELPERS
# ─────────────────────────────────────────────
def fmt_n(n):
    return f"{int(n):,}".replace(",", ".")

def fmt_pct(v, decimals=1):
    return f"{v:.{decimals}f}%"

def channel_active(val):
    if val is None or val == '-' or val == '': return False
    try: return float(val) > 0
    except: return False

def channel_intensity(val):
    if val is None or val == '-' or val == '': return 0
    try:
        v = float(val)
        return v if v > 0 else 0
    except: return 0

# ─────────────────────────────────────────────
# 1. CARGA Y LIMPIEZA
# ─────────────────────────────────────────────
print(f"[1/5] Cargando {INPUT_FILE}...")
df_raw = pd.read_excel(INPUT_FILE, header=1, dtype=str)
df_raw['Hotel'] = df_raw['Hotel'].str.strip()
# Limpiar " Area" del nombre de destino
if 'Destino' in df_raw.columns:
    df_raw['Destino'] = df_raw['Destino'].str.replace(r'\s+Area$', '', regex=True).str.strip()
    # Rename canónico de destinos
    DEST_RENAME = {'Mexico City - Central Mexico': 'Mexico City'}
    df_raw['Destino'] = df_raw['Destino'].replace(DEST_RENAME)
    # Aplicar mapeo manual de hoteles sin clasificar (dest_mapping.py)
    # Solo se aplica a hoteles que AÚN no tienen destino válido en el dataset.
    # Si el dataset nuevo ya trae un destino correcto, NO se pisa.
    try:
        from dest_mapping import DEST_MAPPING
        if DEST_MAPPING:
            _SIN = {'', 'nan', 'sinclasificar', 'sin clasificar', 'none'}
            _sin_mask = (
                df_raw['Destino'].isna() |
                df_raw['Destino'].astype(str).str.strip().str.lower().isin(_SIN)
            )
            _mapped = df_raw.loc[_sin_mask, 'Hotel'].str.strip().map(DEST_MAPPING)
            _needs_map = _mapped.notna()
            df_raw.loc[_needs_map[_needs_map].index, 'Destino'] = _mapped[_needs_map]
            print(f"    [dest_mapping] {_needs_map.sum()} hoteles sin clasificar remapeados "
                  f"({_sin_mask.sum()} sin clasificar en dataset, {(~_sin_mask).sum()} con destino válido intactos)")
        else:
            print("    [dest_mapping] archivo presente pero sin entradas aún")
    except ImportError:
        print("    [dest_mapping] no encontrado — se salta (normal si aún no existe)")
df_raw['HtActive'] = pd.to_numeric(df_raw['HtActive'], errors='coerce').fillna(0).astype(int)

# Compatibilidad: dataset nuevo usa tipo_Ht_contrato_2, dataset viejo usa TipoHotel + Prpios/Terceros
NUEVO_FORMATO = 'tipo_Ht_contrato_2' in df_raw.columns and 'Prpios' not in df_raw.columns

if NUEVO_FORMATO:
    # Dataset nuevo — renombrar columna de tipo
    df_raw = df_raw.rename(columns={'tipo_Ht_contrato_2': 'TipoHotel'})
    # Calcular Prpios y Terceros desde tipo
    TIPO_NORM_RAW = {
        'propio_con_tercero':'Propio_con_tercero',
        'Propio_con_tercero':'Propio_con_tercero',
        'solo_terceros':'sólo terceros',
        'sólo terceros':'sólo terceros',
        'solo_propios':'sólo propio',
        'sólo propio':'sólo propio',
        'solo propio':'sólo propio',
        'sincontrato':'sincontrato',
        'sin_contrato_valido':'sincontrato',
    }
    df_raw['TipoHotel'] = df_raw['TipoHotel'].map(TIPO_NORM_RAW).fillna(df_raw['TipoHotel'])
    df_raw['Prpios']   = df_raw['TipoHotel'].isin(['sólo propio','Propio_con_tercero']).astype(int)
    df_raw['Terceros'] = df_raw['TipoHotel'].isin(['sólo terceros']).astype(int)
