# Sin contratación directa — Independientes (AA-Independent) por región y destino
df_tp_indep = df_tp[df_tp['Corporativo']=='AA-Independent'].copy()
df_pp_indep = df_pp[df_pp['Corporativo']=='AA-Independent'].copy()

